import { drizzle } from "drizzle-orm/d1";
import { env } from "cloudflare:workers";

export const db = drizzle(env.DB);

import React from "react";
import { db } from "@/db";
import { posts } from "@/db/schema";

export const BlogPage = async () => {
  const allPosts = await db.select().from(posts);

  return (
    <div style={{ fontFamily: "sans-serif", padding: "2rem", maxWidth: "800px", margin: "0 auto" }}>
      <h1>Blog Posts</h1>
      {allPosts.length === 0 ? (
        <p>No posts found.</p>
      ) : (
        <ul>
          {allPosts.map((post) => (
            <li key={post.id} style={{ margin: "1rem 0" }}>
              <a href={`/blog/${post.slug}`} style={{ fontSize: "1.2rem", textDecoration: "none", color: "#0070f3" }}>
                {post.title}
              </a>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

import React from "react";

interface PostPageProps {
  title: string;
  content: string;
}

export const PostPage: React.FC<PostPageProps> = ({ title, content }) => {
  return (
    <article style={{ fontFamily: "sans-serif", padding: "2rem", maxWidth: "800px", margin: "0 auto" }}>
      <header style={{ marginBottom: "2rem" }}>
        <h1 style={{ fontSize: "2.5rem", marginBottom: "0.5rem" }}>{title}</h1>
        <p><a href="/blog" style={{ textDecoration: "none", color: "#0070f3" }}>&larr; Back to Blog</a></p>
      </header>
      <div style={{ fontSize: "1.1rem", lineHeight: "1.6", color: "#333" }}>
        {content}
      </div>
    </article>
  );
};

import { render, route } from "rwsdk/router";
import { defineApp } from "rwsdk/worker";
import { eq } from "drizzle-orm";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";
import { Home } from "@/app/pages/home";
import { BlogPage } from "@/app/pages/blog";
import { PostPage } from "@/app/pages/post";
import { db } from "@/db";
import { posts } from "@/db/schema";

export type AppContext = {};

export default defineApp([
  setCommonHeaders(),
  ({ ctx }) => {
    // setup ctx here
    ctx;
  },
  render(Document, [
    route("/", Home),
    route("/blog", BlogPage),
    route("/blog/:slug", async ({ params, response }) => {
      const { slug } = params;
      const post = await db.select().from(posts).where(eq(posts.slug, slug)).get();
      if (!post) {
        response.status = 404;
        return (
          <div style={{ fontFamily: "sans-serif", padding: "2rem", textAlign: "center" }}>
            <h1>404 - Post Not Found</h1>
            <p>The post you are looking for does not exist.</p>
            <p><a href="/blog">Back to Blog</a></p>
          </div>
        );
      }
      return <PostPage title={post.title} content={post.content} />;
    }),
  ]),
]);
